import{_ as a,o as e,c as l,a3 as r,j as t}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"速查页 B　公式速查","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/13.md","filePath":"timeseries/13.md"}'),h={name:"timeseries/13.md"};function n(o,d,i,b,s,u){return e(),l("div",null,[...d[0]||(d[0]=[r('<h1 id="速查页-b-公式速查" tabindex="-1">速查页 B　公式速查 <a class="header-anchor" href="#速查页-b-公式速查" aria-label="Permalink to &quot;速查页 B　公式速查&quot;">​</a></h1><p>本页汇总全书出现的公式，按主题分组，便于复习与临场查阅。</p><h2 id="b1-基本量与平稳性" tabindex="-1">B1 基本量与平稳性 <a class="header-anchor" href="#b1-基本量与平稳性" aria-label="Permalink to &quot;B1 基本量与平稳性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>公式</th></tr></thead><tbody><tr><td>自协方差</td><td>γₖ = Cov(Yₜ, Yₜ₊ₖ) = E[(Yₜ−μ)(Yₜ₊ₖ−μ)]</td></tr><tr><td>自相关</td><td>ρₖ = γₖ / γ₀</td></tr><tr><td>宽平稳三条件</td><td>E(Yₜ)=μ；Var(Yₜ)=γ₀&lt;∞；Cov(Yₜ,Yₜ₊ₖ)=γₖ</td></tr><tr><td>样本自协方差</td><td>γ̂ₖ = (1/n) Σₜ₌₁ⁿ⁻ᵏ (yₜ−ȳ)(yₜ₊ₖ−ȳ)</td></tr><tr><td>白噪声置信带</td><td>±1.96/√n（95%）</td></tr><tr><td>随机游走方差</td><td>Var(Yₜ) = tσ²</td></tr><tr><td>随机游走 ACF</td><td>ρₖ ≈ 1 − k/(2t)</td></tr></tbody></table><h2 id="b2-模型与平稳可逆" tabindex="-1">B2 模型与平稳可逆 <a class="header-anchor" href="#b2-模型与平稳可逆" aria-label="Permalink to &quot;B2 模型与平稳可逆&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>表达式</th><th>平稳条件</th><th>可逆条件</th></tr></thead><tbody><tr><td>MA(q)</td><td>yₜ = μ + εₜ + Σθᵢεₜ₋ᵢ</td><td>恒平稳</td><td>1+θ₁z+…+θ_qz^q=0 根在圆外</td></tr><tr><td>AR(p)</td><td>yₜ = c + Σφᵢyₜ₋ᵢ + εₜ</td><td>1−φ₁z−…−φ_pz^p=0 根在圆外</td><td>恒可逆</td></tr><tr><td>ARMA(p,q)</td><td>两者结合</td><td>由 AR 部分决定</td><td>由 MA 部分决定</td></tr><tr><td>ARIMA(p,d,q)</td><td>φ(B)(1−B)^d yₜ = c + θ(B)εₜ</td><td>差分后平稳</td><td>由 MA 部分决定</td></tr><tr><td>SARIMA</td><td>φ(B)Φ(B^s)(1−B)^d(1−B^s)^D yₜ = c + θ(B)Θ(B^s)εₜ</td><td>双重差分后平稳</td><td>由 MA 与 SMA 决定</td></tr></tbody></table><h2 id="b3-ar-1-与-arma-1-1-的显式结果" tabindex="-1">B3 AR(1) 与 ARMA(1,1) 的显式结果 <a class="header-anchor" href="#b3-ar-1-与-arma-1-1-的显式结果" aria-label="Permalink to &quot;B3 AR(1) 与 ARMA(1,1) 的显式结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>量</th><th>AR(1)：yₜ = φyₜ₋₁ + εₜ</th><th>ARMA(1,1)：yₜ = φyₜ₋₁ + εₜ + θεₜ₋₁</th></tr></thead><tbody><tr><td>均值</td><td>0</td><td>0</td></tr><tr><td>方差</td><td>σ²/(1−φ²)</td><td>σ²(1+2φθ+θ²)/(1−φ²)</td></tr><tr><td>ρ₁</td><td>φ</td><td>(1+φθ)(φ+θ)/(1+2φθ+θ²)</td></tr><tr><td>ρₖ (k≥2)</td><td>φᵏ</td><td>φ^(k−1)ρ₁</td></tr><tr><td>Green 函数 ψ₀</td><td>1</td><td>1</td></tr><tr><td>ψ₁</td><td>φ</td><td>φ + θ</td></tr><tr><td>ψⱼ (j≥2)</td><td>φʲ</td><td>φ^(j−1)(φ+θ)</td></tr></tbody></table><h2 id="b4-信息准则" tabindex="-1">B4 信息准则 <a class="header-anchor" href="#b4-信息准则" aria-label="Permalink to &quot;B4 信息准则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>准则</th><th>公式</th><th>惩罚强度</th><th>目标</th></tr></thead><tbody><tr><td>AIC</td><td>−2lnL + 2k</td><td>最弱</td><td>预测最优</td></tr><tr><td>AICc</td><td>AIC + 2k(k+1)/(n−k−1)</td><td>略强</td><td>小样本的 AIC 修正</td></tr><tr><td>HQ</td><td>−2lnL + 2k ln(ln n)</td><td>中</td><td>折中</td></tr><tr><td>BIC</td><td>−2lnL + k ln n</td><td>最强</td><td>一致估计真阶</td></tr></tbody></table><h2 id="b5-诊断检验" tabindex="-1">B5 诊断检验 <a class="header-anchor" href="#b5-诊断检验" aria-label="Permalink to &quot;B5 诊断检验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检验</th><th>统计量</th><th>原假设</th><th>分布</th></tr></thead><tbody><tr><td>ADF</td><td>t = γ̂/SE(γ̂)</td><td>存在单位根（γ=0）</td><td>Dickey-Fuller（左偏）</td></tr><tr><td>KPSS</td><td>LM = (1/n²)ΣSₜ²/σ̂²</td><td>平稳</td><td>专用分布（右尾）</td></tr><tr><td>Ljung-Box</td><td>Q = n(n+2)Σₖ₌₁^m ρ̂ₖ²/(n−k)</td><td>前 m 阶自相关为零</td><td>χ²(m − 已估参数数)</td></tr><tr><td>Box-Pierce</td><td>Q = n Σρ̂ₖ²</td><td>同上</td><td>χ²(m − 已估参数数)</td></tr><tr><td>Jarque-Bera</td><td>JB = (n/6)[S² + (K−3)²/4]</td><td>正态</td><td>χ²(2)</td></tr><tr><td>ARCH LM</td><td>LM = nR²（eₜ² 对自身滞后回归）</td><td>无 ARCH</td><td>χ²(q)</td></tr></tbody></table><h2 id="b6-预测" tabindex="-1">B6 预测 <a class="header-anchor" href="#b6-预测" aria-label="Permalink to &quot;B6 预测&quot;">​</a></h2>',13),t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"量"),t("th",null,"公式")])]),t("tbody",null,[t("tr",null,[t("td",null,"最优预测"),t("td",{"T+h":""},"ŷ_{T+h} = E(y_")]),t("tr",null,[t("td",null,"预测误差"),t("td",{"T+h−j":""},"e_h = Σⱼ₌₀^{h−1} ψⱼ ε_")]),t("tr",null,[t("td",null,"误差方差"),t("td",null,"Var(e_h) = σ² Σⱼ₌₀^{h−1} ψⱼ²")]),t("tr",null,[t("td",null,"95% 区间"),t("td",null,"ŷ_{T+h} ± 1.96 σ √(Σⱼ₌₀^{h−1} ψⱼ²)")]),t("tr",null,[t("td",null,"平稳模型长期预测"),t("td",null,"ŷ → μ = c/(1−Σφᵢ)")]),t("tr",null,[t("td",null,"含漂移 ARIMA 长期预测"),t("td",null,"ŷ → 斜率 c 的直线，区间按 √h 增长")]),t("tr",null,[t("td",null,"ARIMA(0,1,1) 误差方差"),t("td",null,"σ²[1 + (h−1)(1+θ)²]")])])],-1),r('<h2 id="b7-评价指标" tabindex="-1">B7 评价指标 <a class="header-anchor" href="#b7-评价指标" aria-label="Permalink to &quot;B7 评价指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>公式</th><th>备注</th></tr></thead><tbody><tr><td>RMSE</td><td>√((1/n)Σeₜ²)</td><td>与原序列同量纲；惩罚大误差</td></tr><tr><td>MAE</td><td>(1/n)Σ</td><td>eₜ</td></tr><tr><td>MAPE</td><td>(100/n)Σ</td><td>eₜ/yₜ</td></tr><tr><td>sMAPE</td><td>(100/n)Σ 2</td><td>eₜ</td></tr><tr><td>MASE</td><td>MAE / [(1/(n−m))Σ</td><td>yₜ−yₜ₋ₘ</td></tr><tr><td>DM</td><td>d̄ / √(2π f̂_d(0)/T)</td><td>比较两个模型精度差异</td></tr><tr><td>恒等关系</td><td>RMSE ≥ MAE</td><td>等号仅当所有</td></tr></tbody></table><h2 id="b8-nnar" tabindex="-1">B8 NNAR <a class="header-anchor" href="#b8-nnar" aria-label="Permalink to &quot;B8 NNAR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>量</th><th>公式或说明</th></tr></thead><tbody><tr><td>模型</td><td>ŷₜ = β₀ + Σⱼ₌₁ᵏ βⱼ σ(aⱼ₀ + Σᵢ₌₁ᵖ aⱼᵢ yₜ₋ᵢ)</td></tr><tr><td>输出上界</td><td>ŷ ∈ [β₀ − Σⱼ</td></tr><tr><td>归一化</td><td>y&#39; = (y − min)/(max − min)，min/max 只能取训练前缀</td></tr><tr><td>常见默认</td><td>k ≈ (p+P+1)/2；decay = 0；maxit = 100；repeats = 20</td></tr><tr><td>随机性</td><td>权重初始化；必须 <code>set.seed()</code> 并报告种子</td></tr></tbody></table><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>这门课的主线其实只有一句话：<strong>用尽可能少的假设，把序列中可预测的部分提取出来，并对提取不掉的部分保持诚实。</strong></p><p>三个层次的区分贯穿始终：</p><ol><li><strong>识别</strong>——数据是否支持某类结构？（平稳性、ACF/PACF、单位根）</li><li><strong>估计</strong>——在给定结构下，参数是多少、是否显著？（MLE、标准误、置信区间）</li><li><strong>检验</strong>——这个结构在没见过的数据上还能用吗？（样本外评价、基准对比、DM 检验）</li></ol><p>绝大多数错误，都源于把这三个层次混为一谈——用样本内拟合冒充预测能力，用不拒绝冒充证明，用漂亮的指标冒充有效的模型。把这三层分清楚，这门课就通了。</p>',10)])])}const _=a(h,[["render",n]]);export{c as __pageData,_ as default};
